function createClock(start) {
  let ms = new Date(start).getTime();
  return {
    now: () => new Date(ms),
    add({ days = 0, hours = 0 }) {
      ms += days * 86_400_000 + hours * 3_600_000;
    },
  };
}

const clock = createClock("2026-10-01T09:00:00Z");
console.log(clock.now().toISOString()); // 2026-10-01T09:00:00.000Z
clock.add({ days: 2, hours: 3 });
console.log(clock.now().toISOString()); // 2026-10-03T12:00:00.000Z

