function createTasks(now) {
  const list = [];
  return {
    add(title, dueInDays) {
      list.push({ title, dueAt: new Date(now().getTime() + dueInDays * 86_400_000) });
    },
    overdue() {
      return list.filter((task) => task.dueAt < now()).map((task) => task.title);
    },
  };
}

