function createCleanup() {
  const fns = [];
  return {
    register(fn) {
      fns.push(fn);
    },
    async dispose() {
      let failed = 0;
      for (const fn of [...fns].reverse()) {
        try {
          await fn();
        } catch {
          failed += 1;
        }
      }
      return failed;
    },
  };
}

const stopped = [];
const cleanup = createCleanup();
cleanup.register(() => stopped.push("database"));
cleanup.register(() => { throw new Error("queue stuck"); });
