function sameSet(a, b) {
  if (a.size !== b.size) return false;
  for (const item of a) {
    if (!b.has(item)) return false;
  }
  return true;
}

console.log(
  sameSet(new Set(["home", "work"]), new Set(["work", "home"])),
  sameSet(new Set(["home"]), new Set(["work"])),
  sameSet(new Set(["home"]), new Set(["home", "work"])),
