function firstDifference(a, b) {
  const length = Math.max(a.length, b.length);
  for (let i = 0; i < length; i++) {
    if (a[i] !== b[i]) return `[${i}]: expected "${b[i]}", received "${a[i]}"`;
  }
  return null;
}

console.log(firstDifference(["home", "urgent"], ["home", "later"])); // [1]: expected "later", received "urgent"
console.log(firstDifference(["home"], ["home"])); // null

