async function assertRejects(fn, text) {
  let caught;
  try {
    await fn();
  } catch (error) {
    caught = error;
  }
  if (caught === undefined) throw new Error("did not reject");
  if (!String(caught.message).includes(text)) throw new Error("wrong error");
  return caught;
}

const error = await assertRejects(async () => { throw new Error("You already have 3 open tasks."); }, "open tasks");
console.log(error.message); // You already have 3 open tasks.
